			const stack = new Error().stack;
			if (stack?.includes('render.js')) {
				throw new Error('setAttribute called during hydration');
			}
			return orig.apply(this, arguments);
		};
	},
	after_test() {
		Element.prototype.setAttribute = orig;
	},
